import { test, expect } from '@playwright/test';

test.describe('Pinch-to-Zoom on Product Images', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/products/123');
  });

  test('should successfully pinch-to-zoom on a product image', async ({ page }) => {
    // Verify product image is visible
    const productImage = page.getByRole('img', { name: /product image/i });
    await expect(productImage).toBeVisible();

    // Get initial bounding box
    const initialBox = await productImage.boundingBox();
    expect(initialBox).not.toBeNull();

    // Get initial scale
    const initialScale = await page.evaluate(() => {
      const img = document.querySelector('[data-testid="product-image"]');
      return window.getComputedStyle(img).transform.replace(/matrix\(\d+\s*, \d+\s*, \d+\s*, \d+\)/, '').split(',').map(Number);
    });

    // Pinch in (zoom out)
    await page.evaluate(() => {
      const img = document.querySelector('[data-testid="product-image"]');
      if (img) {
        img.style.transform = 'scale(0.5)';
      }
    });

    // Verify zoomed out state
    const zoomedOutBox = await productImage.boundingBox();
    expect(zoomedOutBox.width).toBeLessThan(initialBox.width);
    expect(zoomedOutBox.height).toBeLessThan(initialBox.height);

    // Pinch out (zoom in)
    await page.evaluate(() => {
      const img = document.querySelector('[data-testid="product-image"]');
      if (img) {
        img.style.transform = 'scale(2)';
      }
    });

    // Verify zoomed in state
    const zoomedInBox = await productImage.boundingBox();
    expect(zoomedInBox.width).toBeGreaterThan(initialBox.width);
    expect(zoomedInBox.height).toBeGreaterThan(initialBox.height);

    // Verify zoom level is reflected in UI
    const zoomLevelIndicator = page.getByText(/2x zoom/i);
    await expect(zoomLevelIndicator).toBeVisible();
  });

  test('should handle zoom out to minimum level and prevent further zoom', async ({ page }) => {
    // Verify product image is visible
    const productImage = page.getByRole('img', { name: /product image/i });
    await expect(productImage).toBeVisible();

    // Pinch in (zoom out)
    await page.evaluate(() => {
      const img = document.querySelector('[data-testid="product-image"]');
      if (img) {
        img.style.transform = 'scale(0.1)';
      }
    });

    // Verify zoomed out state
    const zoomedOutBox = await productImage.boundingBox();
    expect(zoomedOutBox.width).toBeLessThan(100);
    expect(zoomedOutBox.height).toBeLessThan(100);

    // Attempt to zoom out further
    await page.evaluate(() => {
      const img = document.querySelector('[data-testid="product-image"]');
      if (img) {
        img.style.transform = 'scale(0.01)';
      }
    });

    // Verify zoom level is capped at minimum
    const cappedBox = await productImage.boundingBox();
    expect(cappedBox.width).toBeCloseTo(zoomedOutBox.width);
    expect(cappedBox.height).toBeCloseTo(zoomedOutBox.height);

    // Verify zoom level indicator shows minimum
    const zoomLevelIndicator = page.getByText(/min zoom/i);
    await expect(zoomLevelIndicator).toBeVisible();

    // Pinch out (zoom in)
    await page.evaluate(() => {
      const img = document.querySelector('[data-testid="product-image"]');
      if (img) {
        img.style.transform = 'scale(1)';
      }
    });

    // Verify zoom level is reset to default
    const resetBox = await productImage.boundingBox();
    expect(resetBox.width).toBeCloseTo(initialBox.width);
    expect(resetBox.height).toBeCloseTo(initialBox.height);
  });
});
